public static String textMerge(String text, Map<String, String> params) {
        String result = text;
        String regexSearch;
        for (Map.Entry<String, String> entry : params.entrySet()) {
            regexSearch = "(?i)\\{" + entry.getKey() + "\\}";
            result = result.replaceAll(regexSearch, entry.getValue());
        }
        return result;
    }
